-- E3 (Session-Rahmen): Hinweise als KI-Entwurf für die Session-Aufgaben aus dem Szenario Batu.
-- Erzeugt von: node tools/hinweise-e3.mjs migration 20261013175427 hinweise_e3_batu
-- Quelle tools/hinweise-e3/<skill>.mjs, nachgerechnet von tools/hinweise-e3.mjs pruefen, zweitgeprüft
-- (docs/prefill/befunde-hinweise-e3.md). Nicht von Hand ändern.
--
-- Nur Daten. Setzt hints ausschließlich, wo noch keiner steht (hints = []), nur bei Einsatz session, nie VERA8.
-- Jeder Hinweis kommt als status entwurf; das Flag edvance.hinweis_status wird nicht gesetzt, der Trigger
-- hinweise_status_folgt_text macht jeden neuen Text ohnehin zum Entwurf. Aufgabe, Lösung, Status und
-- known_errors bleiben unverändert. Ein zweiter Lauf ändert nichts (Bedingung hints = []).
-- Nebenwirkung: task_solutions_pruef_version zählt tasks.pruef_version der 49 Aufgaben hoch (gewollt: L5 sieht neuen Stand).

update public.task_solutions s
   set hints = v.hints
  from (values
  ('152bcdcd-897b-452b-9a8f-402375540a3f'::uuid, '[{"level":1,"text":"Gesucht ist die Zahl für x. Überlege, welche Rechnung mit x gemacht wird und wie du sie rückgängig machst.","status":"entwurf"},{"level":2,"text":"In 3x = 18 wird x mit 3 multipliziert. Teile deshalb beide Seiten durch 3.","status":"entwurf"},{"level":3,"text":"Wir teilen beide Seiten durch 3: x = 18 : 3. Rechne die Division aus.","status":"entwurf"}]'::jsonb), -- gleichung_einschrittig gleichung-einschrittig-03
  ('fbd28765-b198-4ff6-bdbe-de9ccc5202de'::uuid, '[{"level":1,"text":"Gesucht ist die Zahl für x. Überlege, welche Rechnung mit x gemacht wird und wie du sie rückgängig machst.","status":"entwurf"},{"level":2,"text":"In 4x = 24 wird x mit 4 multipliziert. Teile deshalb beide Seiten durch 4.","status":"entwurf"},{"level":3,"text":"Wir teilen beide Seiten durch 4: x = 24 : 4. Rechne die Division aus.","status":"entwurf"}]'::jsonb), -- gleichung_einschrittig gleichung-einschrittig-06
  ('d19c8070-85d9-44cc-b4cc-eac3e06010d0'::uuid, '[{"level":1,"text":"Gesucht ist die Zahl für x. Überlege, welche Rechnung mit x gemacht wird und wie du sie rückgängig machst.","status":"entwurf"},{"level":2,"text":"Zu x wird 12 addiert. Ziehe deshalb auf beiden Seiten 12 ab.","status":"entwurf"},{"level":3,"text":"Wir ziehen auf beiden Seiten 12 ab: x = 20 − 12. Rechne die Differenz genau in dieser Reihenfolge aus.","status":"entwurf"}]'::jsonb), -- gleichung_einschrittig gleichung-einschrittig-04
  ('bfd877b9-cd3e-490c-82ad-0274b4f85a8b'::uuid, '[{"level":1,"text":"Gesucht ist die Zahl für x. Überlege, welche Rechnung mit x gemacht wird und wie du sie rückgängig machst.","status":"entwurf"},{"level":2,"text":"Zu x wird 7 addiert. Ziehe deshalb auf beiden Seiten 7 ab.","status":"entwurf"},{"level":3,"text":"Wir ziehen auf beiden Seiten 7 ab: x = 12 − 7. Rechne die Differenz genau in dieser Reihenfolge aus.","status":"entwurf"}]'::jsonb), -- gleichung_einschrittig gleichung-einschrittig-01
  ('4f6f7cdd-3415-4185-8eae-95083d061b71'::uuid, '[{"level":1,"text":"Gesucht ist die Zahl für x. Überlege, welche Rechnung mit x gemacht wird und wie du sie rückgängig machst.","status":"entwurf"},{"level":2,"text":"Von x wird 4 abgezogen. Addiere deshalb auf beiden Seiten 4.","status":"entwurf"},{"level":3,"text":"Wir addieren auf beiden Seiten 4: x = 9 + 4. Rechne die Summe aus.","status":"entwurf"}]'::jsonb), -- gleichung_einschrittig gleichung-einschrittig-02
  ('6fc6928a-6ae3-4c32-9c2e-b9a20451b97c'::uuid, '[{"level":1,"text":"Gesucht ist die Zahl für x. Überlege, welche Rechnung mit x gemacht wird und wie du sie rückgängig machst.","status":"entwurf"},{"level":2,"text":"Von x wird 9 abgezogen. Addiere deshalb auf beiden Seiten 9.","status":"entwurf"},{"level":3,"text":"Wir addieren auf beiden Seiten 9: x = 6 + 9. Rechne die Summe aus.","status":"entwurf"}]'::jsonb), -- gleichung_einschrittig gleichung-einschrittig-05
  ('0c3d2396-131a-4cba-bd07-4597d92500cf'::uuid, '[{"level":1,"text":"Die Anzahl der Lösungen erkennst du an der Diskriminante. Prüf zuerst, ob die Gleichung schon die Normalform x² + px + q = 0 hat.","status":"entwurf"},{"level":2,"text":"Teile die ganze Gleichung durch 2: x² − 4x + 4 = 0.","status":"entwurf"},{"level":3,"text":"Jetzt ist p = −4 und q = 4, also D = (−2)² − 4. Denk daran, dass das Quadrat einer negativen Zahl positiv ist, und überlege, was D für die Anzahl bedeutet.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_anzahl quadrgl-anzahl-04
  ('a549083d-c72d-44d6-9aba-a138ad6d2dc0'::uuid, '[{"level":1,"text":"Die Anzahl der Lösungen hängt davon ab, was in der p-q-Formel unter der Wurzel steht. Wie heißt dieser Teil?","status":"entwurf"},{"level":2,"text":"Lies p und q ab: p = 4 und q = 5. Berechne damit die Diskriminante D = (p/2)² − q.","status":"entwurf"},{"level":3,"text":"Wir halbieren p und rechnen D = 2² − 5. Schau dann, ob D positiv, null oder negativ ist; davon hängt die Anzahl der Lösungen ab.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_anzahl quadrgl-anzahl-01
  ('95077a87-7e8a-4463-83b0-dbbf6facc879'::uuid, '[{"level":1,"text":"Bring die Gleichung zuerst in die Normalform x² + px + q = 0. Dann entscheidet die Diskriminante über die Anzahl.","status":"entwurf"},{"level":2,"text":"Multipliziere aus: 10x − x² = 25. Bring alles nach rechts, damit x² mit Plus dasteht: 0 = x² − 10x + 25.","status":"entwurf"},{"level":3,"text":"Mit p = −10 und q = 25 ist p/2 = −5, also D = (−5)² − 25. Denk daran, dass das Quadrat einer negativen Zahl positiv ist.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_anzahl quadrgl-anzahl-05
  ('ef911123-949d-4ea9-a61d-beef95cc8dc0'::uuid, '[{"level":1,"text":"Die Formel für D steht schon in der Aufgabe. Du brauchst dafür nur p und q aus der Gleichung.","status":"entwurf"},{"level":2,"text":"Lies p und q mit ihren Vorzeichen ab: p = −5 und q = −6. Setze beide in D = (p/2)² − q ein.","status":"entwurf"},{"level":3,"text":"Wir halbieren p: p/2 = −2,5, also D = (−2,5)² − (−6). Das Quadrat einer negativen Zahl ist positiv, und minus (−6) heißt plus 6.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_anzahl quadrgl-anzahl-03
  ('9f9ab204-2b5e-49d7-aaab-28ddc96ea8b5'::uuid, '[{"level":1,"text":"Die Formel für D steht schon in der Aufgabe. Du brauchst dafür nur p und q aus der Gleichung.","status":"entwurf"},{"level":2,"text":"Lies p und q mit ihren Vorzeichen ab: p = −6 und q = 8. Setze beide in D = (p/2)² − q ein.","status":"entwurf"},{"level":3,"text":"Wir halbieren p: p/2 = −3, also D = (−3)² − 8. Denk daran, dass das Quadrat einer negativen Zahl positiv ist.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_anzahl quadrgl-anzahl-02
  ('56540a88-7b9e-4935-8702-26f9415e9d14'::uuid, '[{"level":1,"text":"Überlege, welchen Wert die Diskriminante haben muss, wenn es genau eine Lösung gibt.","status":"entwurf"},{"level":2,"text":"Genau eine Lösung heißt D = 0. Stell D für diese Gleichung auf: D = (6/2)² − q.","status":"entwurf"},{"level":3,"text":"Wir rechnen (6/2)² aus; diese Zahl minus q muss null ergeben. Stell nach q um und setz dein q zur Probe ein: Ergibt sich wirklich null?","status":"entwurf"}]'::jsonb), -- gleichung_quadr_anzahl quadrgl-anzahl-06
  ('d7d81e80-6776-4308-a690-29675f7882d4'::uuid, '[{"level":1,"text":"Gesucht sind alle x, für die beide Seiten gleich sind. Teile nicht durch x, sonst geht eine Lösung verloren; bring lieber alles auf eine Seite.","status":"entwurf"},{"level":2,"text":"Bring 12x auf die linke Seite: 3x² − 12x = 0.","status":"entwurf"},{"level":3,"text":"Wir klammern 3x aus: 3x · (x − 4) = 0. Setze jeden Faktor gleich null, löse beide kleinen Gleichungen und trag die kleinere Lösung zuerst ein.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_faktor quadrgl-faktor-03
  ('b47ef7d3-1933-416f-8fe8-edcbc8fe8929'::uuid, '[{"level":1,"text":"Gesucht sind alle Zahlen für x, die die Gleichung erfüllen. Schau, ob in beiden Summanden derselbe Faktor steckt.","status":"entwurf"},{"level":2,"text":"Klammere x aus. Was bleibt von x² − 5x in der Klammer übrig?","status":"entwurf"},{"level":3,"text":"Wir klammern x aus: x · (x − 5) = 0. Setze beide Faktoren gleich null, überlege bei x − 5 genau, wann die Klammer null wird, und trag die kleinere Lösung zuerst ein.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_faktor quadrgl-faktor-01
  ('1c4a31af-20bc-4348-b8d9-cd83b273ff38'::uuid, '[{"level":1,"text":"Links steht schon ein Produkt, rechts steht null. Was weißt du über ein Produkt, das null ergibt?","status":"entwurf"},{"level":2,"text":"Ein Produkt ist null, wenn ein Faktor null ist. Setze deshalb jede Klammer einzeln gleich null: x − 3 = 0 und x + 5 = 0.","status":"entwurf"},{"level":3,"text":"Wir stellen beide Gleichungen nach x um, indem wir die Zahl neben x auf die andere Seite bringen. Achte dabei auf das Vorzeichen und trag die kleinere Lösung zuerst ein.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_faktor quadrgl-faktor-02
  ('9879542e-bb69-41c6-a77f-3916a26ffad1'::uuid, '[{"level":1,"text":"Am Boden hat der Ball die Höhe null. Welche Gleichung entsteht daraus für t?","status":"entwurf"},{"level":2,"text":"Setze h = 0: 20t − 5t² = 0.","status":"entwurf"},{"level":3,"text":"Wir klammern t aus: t · (20 − 5t) = 0. Die Lösung t = 0 ist der Abwurf; löse also 20 − 5t = 0 nach t auf, achte auf das Vorzeichen und rechne, bis t allein steht.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_faktor quadrgl-faktor-05
  ('c3be2e88-1087-479f-bf95-9dbd732efa56'::uuid, '[{"level":1,"text":"Links steht ein Produkt aus zwei Faktoren, rechts steht null. Was folgt daraus für die einzelnen Faktoren?","status":"entwurf"},{"level":2,"text":"Setze jeden der beiden Faktoren einzeln gleich null. Aus dem zweiten Faktor wird die Gleichung 2x − 7 = 0.","status":"entwurf"},{"level":3,"text":"Wir lösen 2x − 7 = 0: Rechne erst auf beiden Seiten + 7 und teile dann durch 2. Vergiss die Lösung aus dem Faktor x nicht und trag die kleinere Lösung zuerst ein.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_faktor quadrgl-faktor-04
  ('90635757-ba7c-4bde-bd7c-04bd79bf8c35'::uuid, '[{"level":1,"text":"Du kennst beide Lösungen und suchst die Zahl b. Überlege, wie die Gleichung nach dem Ausklammern aussieht.","status":"entwurf"},{"level":2,"text":"Klammere x aus: x · (2x + b) = 0.","status":"entwurf"},{"level":3,"text":"Die Lösung 3 macht den zweiten Faktor null, also setzen wir x = 3 ein: 2 · 3 + b = 0. Stell diese Gleichung nach b um und achte auf das Vorzeichen.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_faktor quadrgl-faktor-06
  ('1f2a206f-1f63-4866-b446-c8305de6b725'::uuid, '[{"level":1,"text":"Für die p-q-Formel darf vor x² keine Zahl stehen. Was musst du deshalb zuerst tun?","status":"entwurf"},{"level":2,"text":"Teile die ganze Gleichung durch 2: x² − 2x − 3 = 0.","status":"entwurf"},{"level":3,"text":"Jetzt ist p = −2 und q = −3, also x = 1 ± √(1 + 3). Rechne die Wurzel aus, dann einmal minus und einmal plus, und trag die kleinere Lösung zuerst ein.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_formel quadrgl-formel-03
  ('1271aabc-2cc1-4b2e-a6c5-d7512c7a38ee'::uuid, '[{"level":1,"text":"Gefragt ist die längere Seite. Nenne die Breite x und überlege, wie du die Länge mit x ausdrückst.","status":"entwurf"},{"level":2,"text":"Die Länge ist x + 4, also x · (x + 4) = 60; bring alles auf eine Seite: x² + 4x − 60 = 0.","status":"entwurf"},{"level":3,"text":"Mit p = 4 und q = −60 ergibt die p-q-Formel x = −2 ± √(4 + 60). Nur die positive Breite ist sinnvoll; rechne danach + 4, denn gefragt ist die längere Seite.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_formel quadrgl-formel-05
  ('5b36238f-c64c-4578-bd63-55249f185c78'::uuid, '[{"level":1,"text":"Nenne die Wegbreite x. Überlege, wie lang und wie breit Beet und Weg zusammen sind.","status":"entwurf"},{"level":2,"text":"Der Weg liegt auf beiden Seiten, also sind Beet und Weg zusammen 20 + 2x lang und 15 + 2x breit: (20 + 2x) · (15 + 2x) = 500.","status":"entwurf"},{"level":3,"text":"Ausmultiplizieren, 500 abziehen und durch 4 teilen ergibt x² + 17,5x − 50 = 0, also x = −8,75 ± √(76,5625 + 50). Nur die positive Breite ist sinnvoll.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_formel quadrgl-formel-06
  ('b6e77404-2577-4e03-b4ce-cb61a5f6a5f9'::uuid, '[{"level":1,"text":"Die Gleichung hat schon die Normalform x² + px + q = 0. Welche Formel löst solche Gleichungen?","status":"entwurf"},{"level":2,"text":"Lies p und q ab: p = 2 und q = −15. Achte beim Ablesen auf die Vorzeichen.","status":"entwurf"},{"level":3,"text":"Wir setzen ein: x = −1 ± √(1 + 15). Rechne die Wurzel aus, dann einmal minus und einmal plus, und trag die kleinere Lösung zuerst ein.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_formel quadrgl-formel-01
  ('725448a1-10e2-4e88-beb8-fe57f6e54d06'::uuid, '[{"level":1,"text":"Die Gleichung hat schon die Normalform x² + px + q = 0. Welche Formel löst solche Gleichungen?","status":"entwurf"},{"level":2,"text":"Lies p und q ab: p = 4 und q = −1. Achte beim Ablesen auf die Vorzeichen.","status":"entwurf"},{"level":3,"text":"Wir setzen ein: x = −2 ± √(4 + 1) = −2 ± √5. Rechne √5 mit dem Taschenrechner, dann minus und plus; runde auf zwei Stellen nach dem Komma, kleinere Lösung zuerst.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_formel quadrgl-formel-04
  ('43f39bc1-e7b4-48e6-8b77-ff8e41e77142'::uuid, '[{"level":1,"text":"Die Gleichung hat schon die Normalform x² + px + q = 0. Welche Formel löst solche Gleichungen?","status":"entwurf"},{"level":2,"text":"Lies p und q ab: p = −6 und q = 5. Achte beim Ablesen auf die Vorzeichen.","status":"entwurf"},{"level":3,"text":"Wir setzen ein: x = 3 ± √(9 − 5), denn −p/2 ist hier positiv. Rechne die Wurzel aus, dann einmal minus und einmal plus, und trag die kleinere Lösung zuerst ein.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_formel quadrgl-formel-02
  ('504bbd98-9c80-4124-a66a-9dc7b6651bb9'::uuid, '[{"level":1,"text":"Links steht ein Quadrat, rechts eine Zahl. Welche Zahlen ergeben quadriert 25?","status":"entwurf"},{"level":2,"text":"Zieh auf beiden Seiten die Wurzel; dabei entstehen zwei Gleichungen: x − 2 = 5 oder x − 2 = −5.","status":"entwurf"},{"level":3,"text":"Wir lösen beide Gleichungen, indem wir auf beiden Seiten + 2 rechnen. Achte auf das Vorzeichen und trag die kleinere Lösung zuerst ein.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_wurzel quadrgl-wurzel-03
  ('4d1a2438-3610-4dc9-b5be-8d35cb5199bd'::uuid, '[{"level":1,"text":"In der Gleichung steht x nur als x². Bring x² allein auf eine Seite und zieh dann die Wurzel.","status":"entwurf"},{"level":2,"text":"Rechne auf beiden Seiten + 18: 2x² = 18.","status":"entwurf"},{"level":3,"text":"Wir teilen durch 2: x² = 9. Jetzt ziehst du die Wurzel; denk an beide Vorzeichen und trag die kleinere Lösung zuerst ein.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_wurzel quadrgl-wurzel-02
  ('cd6693f5-cc93-4628-baf9-f45436706641'::uuid, '[{"level":1,"text":"Bring x² allein auf eine Seite und zieh dann die Wurzel. Denk daran, dass es zwei Lösungen gibt.","status":"entwurf"},{"level":2,"text":"Teile beide Seiten durch 3: x² = 20.","status":"entwurf"},{"level":3,"text":"Wir ziehen die Wurzel: x = √20 oder x = −√20. Rechne √20 mit dem Taschenrechner, runde auf zwei Stellen nach dem Komma und trag die kleinere Lösung zuerst ein.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_wurzel quadrgl-wurzel-04
  ('3a42b89c-7f8a-4b64-94ff-d1d4ac576c32'::uuid, '[{"level":1,"text":"Nenne die ursprüngliche Seite x; die neue Seite ist dann um 3 cm länger. Stell mit dem Flächeninhalt eine Gleichung auf.","status":"entwurf"},{"level":2,"text":"Die neue Seite ist x + 3, also gilt (x + 3)² = 121. Am schnellsten geht es, wenn du jetzt die Wurzel ziehst.","status":"entwurf"},{"level":3,"text":"Wir ziehen die Wurzel: x + 3 = 11 oder x + 3 = −11. Rechne auf beiden Seiten − 3; gefragt ist die ursprüngliche Seite, und nur eine positive Länge ist sinnvoll.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_wurzel quadrgl-wurzel-06
  ('bc0cdfe9-2416-4d02-a623-feb820083f07'::uuid, '[{"level":1,"text":"Nenne die Breite x; dann kannst du auch die Länge mit x ausdrücken. Stell mit dem Flächeninhalt eine Gleichung auf.","status":"entwurf"},{"level":2,"text":"Die Länge ist 2x, also gilt x · 2x = 98.","status":"entwurf"},{"level":3,"text":"Wir fassen zusammen und teilen durch 2: 2x² = 98, also x² = 49. Zieh die Wurzel; als Breite zählt nur die positive Lösung.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_wurzel quadrgl-wurzel-05
  ('9264f90a-1f7b-4170-97da-198c1acc89a3'::uuid, '[{"level":1,"text":"Gesucht sind alle Zahlen, die mit sich selbst multipliziert 49 ergeben. Denk daran, dass es mehr als eine gibt.","status":"entwurf"},{"level":2,"text":"Zieh auf beiden Seiten die Wurzel. Dabei entstehen zwei Lösungen, eine positive und eine negative.","status":"entwurf"},{"level":3,"text":"Wir erhalten x = √49 oder x = −√49. Rechne √49 aus und trag die kleinere Lösung zuerst ein.","status":"entwurf"}]'::jsonb), -- gleichung_quadr_wurzel quadrgl-wurzel-01
  ('e8348c89-67cb-4650-be91-235e69321776'::uuid, '[{"level":1,"text":"Gesucht ist die Zahl für x. Überlege, welche Rechnung du zuerst rückgängig machst: das Plus oder das Mal.","status":"entwurf"},{"level":2,"text":"Rechne zuerst auf beiden Seiten − 4: 2x = 16. Links steht jetzt noch 2x, nicht x.","status":"entwurf"},{"level":3,"text":"Aus 2x = 16 teilen wir beide Seiten durch 2: x = 16 : 2. Rechne die Division aus.","status":"entwurf"}]'::jsonb), -- gleichung_zweischrittig gleichung-zweischrittig-02
  ('7976c81f-9b0b-46d8-a0d1-b5b6cc3bc992'::uuid, '[{"level":1,"text":"Gesucht ist die Zahl für x. Überlege, welche Rechnung du zuerst rückgängig machst: das Plus oder das Mal.","status":"entwurf"},{"level":2,"text":"Rechne zuerst auf beiden Seiten − 6: 3x = 18. Links steht jetzt noch 3x, nicht x.","status":"entwurf"},{"level":3,"text":"Aus 3x = 18 teilen wir beide Seiten durch 3: x = 18 : 3. Rechne die Division aus.","status":"entwurf"}]'::jsonb), -- gleichung_zweischrittig gleichung-zweischrittig-01
  ('17f3e728-2249-42ba-b5bf-c2a4b344dd00'::uuid, '[{"level":1,"text":"Gesucht ist die Zahl für x. Überlege, welche Rechnung du zuerst rückgängig machst: das Plus oder das Mal.","status":"entwurf"},{"level":2,"text":"Rechne zuerst auf beiden Seiten − 9: 3x = 21. Links steht jetzt noch 3x, nicht x.","status":"entwurf"},{"level":3,"text":"Aus 3x = 21 teilen wir beide Seiten durch 3: x = 21 : 3. Rechne die Division aus.","status":"entwurf"}]'::jsonb), -- gleichung_zweischrittig gleichung-zweischrittig-05
  ('b01451c0-53e5-4da7-9591-280448264835'::uuid, '[{"level":1,"text":"Gesucht ist die Zahl für x. Überlege, welche Rechnung du zuerst rückgängig machst: das Plus oder das Mal.","status":"entwurf"},{"level":2,"text":"Rechne zuerst auf beiden Seiten − 8: 4x = 32. Links steht jetzt noch 4x, nicht x.","status":"entwurf"},{"level":3,"text":"Aus 4x = 32 teilen wir beide Seiten durch 4: x = 32 : 4. Rechne die Division aus.","status":"entwurf"}]'::jsonb), -- gleichung_zweischrittig gleichung-zweischrittig-04
  ('9d15a93e-961b-4569-be8b-c4482dc98301'::uuid, '[{"level":1,"text":"Gesucht ist die Zahl für x. Überlege, welche Rechnung du zuerst rückgängig machst: das Plus oder das Mal.","status":"entwurf"},{"level":2,"text":"Rechne zuerst auf beiden Seiten − 10: 5x = 35. Links steht jetzt noch 5x, nicht x.","status":"entwurf"},{"level":3,"text":"Aus 5x = 35 teilen wir beide Seiten durch 5: x = 35 : 5. Rechne die Division aus.","status":"entwurf"}]'::jsonb), -- gleichung_zweischrittig gleichung-zweischrittig-03
  ('ff5710af-0c0a-47e5-9a57-b2a5bb4ef82d'::uuid, '[{"level":1,"text":"Gesucht ist die Zahl für x. Überlege, welche Rechnung du zuerst rückgängig machst: das Plus oder das Mal.","status":"entwurf"},{"level":2,"text":"Rechne zuerst auf beiden Seiten − 12: 6x = 30. Links steht jetzt noch 6x, nicht x.","status":"entwurf"},{"level":3,"text":"Aus 6x = 30 teilen wir beide Seiten durch 6: x = 30 : 6. Rechne die Division aus.","status":"entwurf"}]'::jsonb), -- gleichung_zweischrittig gleichung-zweischrittig-06
  ('02b24419-d7e8-40b8-8b74-ef3b4e806b3f'::uuid, '[{"level":1,"text":"Ausklammern heißt: Du suchst eine Zahl, die in beiden Summanden steckt. „So weit wie möglich“ heißt, du nimmst die größte solche Zahl.","status":"entwurf"},{"level":2,"text":"Suche die größte Zahl, durch die sich 12 und 18 beide ohne Rest teilen lassen.","status":"entwurf"},{"level":3,"text":"Wir klammern 6 aus: Teile 12x und 18 jeweils durch 6 und schreib die Ergebnisse in die Klammer. Rechne zur Probe die Klammer wieder aus und vergleiche mit den Antworten.","status":"entwurf"}]'::jsonb), -- term_ausklammern term-ausklammern-06
