  ('e96cd37d-0254-4051-bf2d-71a6f7fa2aaf'::uuid, '[{"level":1,"text":"Stell dir die Rechnung am Zahlenstrahl vor. Wo startest du, und in welche Richtung gehst du?","status":"entwurf"},{"level":2,"text":"Du startest bei −3 und gehst 5 Schritte nach links.","status":"entwurf"},{"level":3,"text":"Von der 0 bis −3 sind es schon 3 Schritte, dann kommen noch 5 dazu. Zähl beide zusammen; das Ergebnis bleibt negativ.","status":"entwurf"}]'::jsonb), -- vorzeichen_add_sub vorzeichen-addieren-01
  ('17674b19-fe14-42ca-98db-6598fa8c5a3a'::uuid, '[{"level":1,"text":"Stell dir die Rechnung am Zahlenstrahl vor. Wo startest du, und in welche Richtung gehst du?","status":"entwurf"},{"level":2,"text":"Du startest bei −4 und gehst 9 Schritte nach rechts.","status":"entwurf"},{"level":3,"text":"Nach 4 Schritten bist du bei 0. Es bleiben noch 9 − 4 Schritte nach rechts, also ins Plus.","status":"entwurf"}]'::jsonb), -- vorzeichen_add_sub vorzeichen-addieren-05
  ('27f51c08-6a47-4ceb-b189-f5f07cbcf1cf'::uuid, '[{"level":1,"text":"Stell dir die Rechnung am Zahlenstrahl vor. Wo startest du, und in welche Richtung gehst du?","status":"entwurf"},{"level":2,"text":"Du startest bei −6 und gehst 2 Schritte nach links.","status":"entwurf"},{"level":3,"text":"Von der 0 bis −6 sind es schon 6 Schritte, dann kommen noch 2 dazu. Zähl beide zusammen; das Ergebnis bleibt negativ.","status":"entwurf"}]'::jsonb), -- vorzeichen_add_sub vorzeichen-addieren-04
  ('c92aa7e8-1e2d-4c80-a1fc-0fe4fedd86b0'::uuid, '[{"level":1,"text":"Stell dir die Rechnung am Zahlenstrahl vor. Wo startest du, und in welche Richtung gehst du?","status":"entwurf"},{"level":2,"text":"Du startest bei −7 und gehst 4 Schritte nach rechts.","status":"entwurf"},{"level":3,"text":"Mit 4 Schritten nach rechts kommst du nicht bis zur 0; es fehlen noch 7 − 4 Schritte. So weit liegst du links von der 0, also im Minus.","status":"entwurf"}]'::jsonb), -- vorzeichen_add_sub vorzeichen-addieren-02
  ('3b44eada-3589-4bdb-a33b-2fb2ca0a1726'::uuid, '[{"level":1,"text":"Stell dir die Rechnung am Zahlenstrahl vor. Wo startest du, und in welche Richtung gehst du?","status":"entwurf"},{"level":2,"text":"Du startest bei −9 und gehst 5 Schritte nach rechts.","status":"entwurf"},{"level":3,"text":"Mit 5 Schritten nach rechts kommst du nicht bis zur 0; es fehlen noch 9 − 5 Schritte. So weit liegst du links von der 0, also im Minus.","status":"entwurf"}]'::jsonb), -- vorzeichen_add_sub vorzeichen-addieren-07
  ('3e6fb055-111e-4888-9177-d2b17dd0fc54'::uuid, '[{"level":1,"text":"Stell dir die Rechnung am Zahlenstrahl vor. Wo startest du, und in welche Richtung gehst du?","status":"entwurf"},{"level":2,"text":"Du startest bei 2 und gehst 9 Schritte nach links.","status":"entwurf"},{"level":3,"text":"Nach 2 Schritten bist du bei 0. Es bleiben noch 9 − 2 Schritte nach links, also ins Minus.","status":"entwurf"}]'::jsonb), -- vorzeichen_add_sub vorzeichen-addieren-03
  ('738de19f-d3c9-43a0-b5ce-af6e30752c75'::uuid, '[{"level":1,"text":"Stell dir die Rechnung am Zahlenstrahl vor. Wo startest du, und in welche Richtung gehst du?","status":"entwurf"},{"level":2,"text":"Du startest bei 3 und gehst 8 Schritte nach links.","status":"entwurf"},{"level":3,"text":"Nach 3 Schritten bist du bei 0. Es bleiben noch 8 − 3 Schritte nach links, also ins Minus.","status":"entwurf"}]'::jsonb) -- vorzeichen_add_sub vorzeichen-addieren-06
  ) as v(task_id, hints)
 where s.task_id = v.task_id
   and coalesce(s.hints, '[]'::jsonb) = '[]'::jsonb
   and exists (select 1 from public.tasks t
                where t.id = s.task_id
                  and 'session' = any (t.einsatz)
                  and t.source is distinct from 'VERA8_IQB');
